"""Build the offline manual from current UI screenshots.

.venv/bin/python docs/capture_manual_screenshots.py /tmp/panda-manual-images
.venv/bin/python docs/build_manual.py /tmp/panda-manual-images
"""
from pathlib import Path
import base64
import sys
ROOT=Path(__file__).resolve().parents[1]
IMAGES=Path(sys.argv[1] if len(sys.argv)>1 else '/tmp/panda-manual-images')
sections=[]
def table(headers,rows,cls=''):
    return '<div class="table-wrap"><table class="'+cls+'"><thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def fig(name,caption,pins=()):
    src='data:image/png;base64,'+base64.b64encode((IMAGES/(name+'.png')).read_bytes()).decode()
    return '<figure><div class="shot"><button class="zoom" aria-label="放大：'+caption+'"><img src="'+src+'" alt="'+caption+'"></button>'+''.join(f'<span class="pin" style="left:{x}%;top:{y}%" aria-hidden="true">{n}</span>' for n,x,y in pins)+'</div><figcaption>'+caption+' <span>点击图片放大 · Esc 关闭</span></figcaption></figure>'
def note(text,kind='tip'):
    return f'<div class="note {kind}">{text}</div>'
def cards(items):
    return '<div class="cards">'+''.join(f'<article class="card"><span class="card-index">{i:02d}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(items,1))+'</div>'
def sec(id,num,title,lead,body):
    sections.append((id,num,title))
    return f'<section id="{id}"><div class="section-heading"><span class="section-num">{num}</span><div><h2>{title}</h2><p class="lead">{lead}</p></div></div>{body}</section>'
