css=r'''
:root{--paper:#f5f7fb;--ink:#17263b;--muted:#62718a;--line:#e1e7f0;--blue:#245edb;--teal:#087f80;--sidebar:246px}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:28px}body{margin:0;color:var(--ink);background:var(--paper);font:15px/1.85 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}a{color:var(--blue);text-decoration:none}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #e4a84c;outline-offset:3px}[hidden]{display:none!important}.toc{width:var(--sidebar);position:fixed;inset:0 auto 0 0;background:#fff;border-right:1px solid var(--line);padding:30px 22px;overflow:auto;z-index:20}.brand{font-weight:850;font-size:19px;letter-spacing:1px;display:flex;align-items:center;gap:10px}.brand-icon{width:33px;height:33px;display:grid;place-items:center;background:var(--ink);color:white;border-radius:10px;font-size:15px}.toc-sub{color:var(--muted);font-size:12px;margin:8px 0 30px}.toc-label{font-size:11px;letter-spacing:2px;color:#8290a4;margin:20px 8px 10px}.toc nav a{display:flex;gap:9px;border-radius:8px;padding:8px;margin:2px 0;color:#53617a;font-size:12px;line-height:1.5}.toc nav a em{font-style:normal;font-size:11px;color:#96a3b8;min-width:18px}.toc nav a.active,.toc nav a:hover{background:#edf3ff;color:var(--blue)}.toc-bottom{margin-top:25px;padding:16px 8px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}.toc-bottom strong{display:block;color:var(--ink);margin-bottom:4px}.main{margin-left:var(--sidebar);max-width:1510px;padding:0 58px 60px}.topbar{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding:19px 0;font-size:12px;color:var(--muted);gap:12px}.topbar button{border:1px solid var(--line);background:white;border-radius:7px;padding:7px 13px;color:var(--ink)}.topbar .menu-toggle{display:none}.hero{padding:57px 0 35px}.eyebrow{color:var(--blue);font-size:11px;font-weight:800;letter-spacing:2px;display:flex;align-items:center;gap:9px}.eyebrow:before{content:"";width:20px;height:2px;background:var(--blue)}h1{font-size:clamp(32px,3.6vw,55px);letter-spacing:-1.7px;line-height:1.25;margin:20px 0;color:#14223b}h1 span{color:var(--blue)}.hero-desc{font-size:16px;color:var(--muted);max-width:670px;margin:0 0 22px}.badges{display:flex;flex-wrap:wrap;gap:8px}.badges span{background:white;border:1px solid var(--line);border-radius:100px;padding:4px 11px;font-size:11px;color:#65758e}.hero-panel{margin-top:30px;border-radius:16px;background:#14253d;color:white;padding:27px 30px;position:relative;overflow:hidden}.hero-panel:after{content:"";position:absolute;width:300px;height:300px;right:-160px;top:-155px;border:42px solid #244c7e;border-radius:50%;opacity:.6;pointer-events:none}.hero-panel-label{font-size:10px;letter-spacing:2px;color:#95b6e8;margin-bottom:15px}.hero-path{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;position:relative;z-index:1}.hero-path a{color:white;display:block;border-left:2px solid #437dcc;padding-left:14px}.hero-path small{display:block;color:#9eb2cc;font-size:11px}.hero-path strong{font-size:17px;display:block}.hero-path span{font-size:11px;color:#b4c3d7}.hero .note{margin-top:20px}section{padding:39px 0 17px;border-top:1px solid var(--line);margin-top:20px}.section-heading{display:flex;gap:19px;align-items:flex-start;margin-bottom:24px}.section-num{font-size:12px;color:var(--blue);font-weight:750;border:1px solid #d3e0f8;border-radius:8px;background:#eaf0fd;padding:5px 9px;line-height:1.5;margin-top:3px}h2{font-size:26px;line-height:1.4;letter-spacing:-.5px;margin:0 0 9px}h3{font-size:18px;line-height:1.5;margin:28px 0 12px}h4{font-size:14px;margin:0 0 10px}.lead{color:var(--muted);margin:0;font-size:14px}p{margin:12px 0}.table-wrap{overflow:auto;margin:20px 0;border:1px solid var(--line);border-radius:10px;background:#fff}table{border-collapse:collapse;width:100%;min-width:540px;text-align:left;font-size:13px;line-height:1.8}th{background:#edf1f7;color:#54627a;font-size:12px;font-weight:650;white-space:nowrap;padding:12px 16px}td{border-top:1px solid var(--line);padding:14px 16px;vertical-align:top}td:first-child{font-weight:650;color:#253c5a;min-width:140px}td code{overflow-wrap:anywhere}.parameter-table{min-width:770px}.parameter-table td:first-child{width:235px}.parameter-table td:nth-child(2),.parameter-table td:nth-child(3){white-space:nowrap;font-size:12px}.note{padding:15px 19px;border-left:3px solid #7fb4dc;background:#eaf3fb;border-radius:0 9px 9px 0;font-size:13px;margin:20px 0;color:#3c5975}.note.important{background:#fff3df;border-color:#d4a047;color:#77541d}.note strong{color:inherit}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:22px 0}.card{border:1px solid var(--line);background:#fff;border-radius:12px;padding:23px;position:relative}.card-index{font:11px/1.5 ui-monospace,monospace;color:var(--blue);display:block}.card h3{margin:12px 0 9px;font-size:16px}.card p{font-size:13px;color:var(--muted);margin:0}.steps{counter-reset:step;list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:17px;margin:25px 0}.steps li{counter-increment:step;position:relative;padding:22px 23px 22px 58px;background:#fff;border:1px solid var(--line);border-radius:12px}.steps li:before{content:counter(step);position:absolute;left:20px;top:23px;border-radius:50%;background:#edf3ff;color:var(--blue);width:25px;height:25px;text-align:center;font-size:12px;font-weight:750;line-height:25px}.steps li strong{font-size:15px}.steps li p{font-size:13px;color:var(--muted);margin:8px 0 0}figure{margin:25px 0}.shot{position:relative;border-radius:12px;overflow:hidden;box-shadow:0 8px 24px #162f5414;background:#16253b}.zoom{display:block;width:100%;padding:0;border:0;background:transparent;cursor:zoom-in}.zoom img{width:100%;height:auto;display:block}.pin{position:absolute;transform:translate(-50%,-50%);width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:#ffd87c;color:#1a2b40;font-weight:850;border:2px solid white;font-size:12px;box-shadow:0 2px 7px #0005;pointer-events:none}figcaption{font-size:12px;color:var(--muted);padding:11px 4px;display:flex;justify-content:space-between;gap:15px}figcaption span{font-size:11px;white-space:nowrap;color:#8694a9}.callouts{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:20px 0 26px}.callouts>div{display:flex;gap:10px}.callouts b{flex:none;display:grid;place-items:center;background:#ffe6af;border-radius:50%;width:23px;height:23px;font-size:11px;margin-top:3px}.callouts p{font-size:12px;color:var(--muted);margin:0}.callouts strong{display:block;color:var(--ink);font-size:13px}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:20px 0}.two-col>div{min-width:0}.two-col p{font-size:13px;color:var(--muted)}pre{background:#172940;color:#d8e6f6;padding:19px 21px;border-radius:10px;overflow:auto;font:12px/1.95 ui-monospace,SFMono-Regular,Consolas,"PingFang SC",monospace;white-space:pre-wrap;overflow-wrap:anywhere;margin:12px 0}.prompt{background:#fff;color:#365171;border:1px solid var(--line)}code{font:12px/1.7 ui-monospace,Consolas,monospace;border-radius:4px;background:#eaf0f7;padding:2px 5px;color:#23527b;overflow-wrap:anywhere}.flow{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:24px;background:#eef3fb;border-radius:12px;margin:24px 0}.flow div{font-size:14px;font-weight:700}.flow small{font-weight:400;color:var(--muted);font-size:11px;display:block}.flow>span{color:#8aa5c6}.status-strip{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:26px 0}.status-strip>span:not(:nth-child(2)):not(:nth-child(4)){border-radius:7px;padding:6px 12px;font-size:12px;font-weight:650}.pending{background:#e4efff;color:#245edb}.processing{background:#ece6ff;color:#7751be}.sent{background:#def5eb;color:#087b5b}.failed{background:#fee8e7;color:#ac4b46}.skipped{background:#e5e9ef;color:#68778b}.param-search{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:24px;font-size:12px}.param-search input{background:white;border:1px solid var(--line);border-radius:7px;padding:10px 13px;flex:1;min-width:180px;font-size:13px}.param-search span{color:var(--muted)}details{border:1px solid var(--line);border-radius:9px;background:#fff;margin:10px 0;padding:0 19px}summary{cursor:pointer;font-size:14px;font-weight:650;padding:17px 0}details>div{font-size:13px;color:var(--muted);padding:0 0 18px}details[open] summary{color:var(--blue)}.figure-key{font-size:12px;color:var(--muted)}.source-note{font-size:12px;color:#8694a9;border-top:1px solid var(--line);padding-top:20px}footer{font-size:12px;color:var(--muted);display:flex;justify-content:space-between;margin-top:38px;padding-top:20px;border-top:1px solid var(--line)}.top-link{position:fixed;bottom:24px;right:24px;color:var(--blue);border:1px solid #d6e2f6;background:#fff;border-radius:9px;padding:8px 12px;font-size:12px;z-index:10;box-shadow:0 3px 12px #13213b0c}dialog{width:calc(100vw - 36px);max-width:1800px;height:calc(100vh - 36px);max-height:calc(100vh - 36px);padding:20px;background:#0e1b2d;color:#fff;border:1px solid #365170;border-radius:12px}dialog::backdrop{background:#081222dc}dialog .viewer-bar{display:flex;justify-content:space-between;align-items:center;gap:16px;font-size:12px;height:34px;margin-bottom:12px}dialog button{background:#263e5d;border:1px solid #4b6484;border-radius:6px;padding:5px 14px;color:#fff}.viewer-image{height:calc(100% - 50px);overflow:auto;display:flex;align-items:flex-start;justify-content:center}.viewer-image img{max-width:100%;height:auto;object-fit:contain}.no-js{font-size:12px;color:var(--muted)}
@media(min-width:1800px){.main{margin-right:auto;margin-left:calc(var(--sidebar) + (100vw - var(--sidebar) - 1510px)/2)}}
@media(max-width:1150px){:root{--sidebar:216px}.main{padding:0 30px 40px}.toc{padding:25px 16px}.cards{gap:12px}.card{padding:18px}.callouts{grid-template-columns:repeat(2,1fr)}.pin{width:22px;height:22px;font-size:10px}}
@media(max-width:800px){.toc{display:none;width:240px;box-shadow:0 0 0 100vw #11253b55}.toc.open{display:block}.main{margin:0;padding:0 20px 35px}.topbar .menu-toggle{display:inline-block}.topbar{font-size:10px;flex-wrap:wrap}.hero{padding:34px 0 24px}h1{font-size:34px}.hero-desc{font-size:14px}.hero-panel{padding:22px}.hero-path{grid-template-columns:1fr 1fr;gap:20px}.section-heading{gap:12px}h2{font-size:22px}.steps,.two-col,.cards{grid-template-columns:1fr}.callouts{grid-template-columns:1fr 1fr}.flow{flex-wrap:wrap;gap:14px}.flow div{width:40%}.flow>span:nth-child(4){display:none}figcaption{display:block}figcaption span{display:block;margin-top:4px}.pin{width:18px;height:18px;font-size:9px;border-width:1px}.top-link{right:14px;bottom:15px}dialog{padding:10px;width:calc(100vw - 12px);height:calc(100vh - 12px)}.viewer-image{justify-content:flex-start}.viewer-image img{min-width:1100px;max-width:none}.source-note{font-size:11px}footer{display:block}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
@page{size:A4;margin:14mm}
@media print{body{background:white;color:#142238;font-size:10px;line-height:1.65}.toc,.topbar,.top-link,dialog,.param-search{display:none!important}.main{margin:0;max-width:none;padding:0}.hero{padding:5px 0 18px}h1{font-size:30px}.hero-desc{font-size:12px}.hero-panel{padding:15px;-webkit-print-color-adjust:exact;print-color-adjust:exact}.hero-path strong{font-size:12px}.hero-path small,.hero-path span{font-size:9px}h2{font-size:19px}h3{font-size:14px}section{padding:22px 0 8px;margin-top:16px}.section-heading{margin-bottom:15px;break-after:avoid}.lead{font-size:10px}.table-wrap{overflow:visible;break-inside:auto}table,.parameter-table{min-width:0;font-size:9px;line-height:1.6}th{font-size:9px;padding:7px}td{padding:8px;min-width:0!important}td:first-child{min-width:0}.parameter-table td:first-child{width:160px}.parameter-table td:nth-child(2),.parameter-table td:nth-child(3){font-size:9px;white-space:normal}tr{break-inside:avoid}thead{display:table-header-group}figure{break-inside:avoid;box-shadow:none}.shot{box-shadow:none}.pin,.note,.status-strip span{print-color-adjust:exact;-webkit-print-color-adjust:exact}figcaption{font-size:9px}figcaption span{display:none}.cards{gap:10px}.card{padding:13px;break-inside:avoid}.card h3{font-size:12px}.card p,.steps li p,.callouts p{font-size:10px}.steps{gap:10px}.steps li{padding:14px 14px 14px 43px;break-inside:avoid}.steps li:before{left:12px;top:15px}.steps li strong{font-size:11px}.note{font-size:10px;break-inside:avoid}.two-col p,details>div,summary{font-size:10px}details{break-inside:avoid;padding:0 10px}summary{padding:10px 0}.source-note,footer{font-size:9px}pre,code{font-size:9px}pre{padding:12px}p,li{orphans:3;widows:3}.cards,.steps,.callouts,.two-col{grid-template-columns:1fr 1fr}.flow{font-size:10px;padding:15px}.flow div{font-size:11px}.flow small{font-size:9px}.hero-path{grid-template-columns:repeat(4,1fr)}.hero-panel:after{display:none}}
'''
js=r'''
const toc=document.querySelector('.toc');const nav=[...document.querySelectorAll('.toc nav a')];
document.querySelector('.menu-toggle').addEventListener('click',()=>{const open=toc.classList.toggle('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded',String(open))});
nav.forEach(a=>a.addEventListener('click',()=>{toc.classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){toc.classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')}});
const sections=[...document.querySelectorAll('main section')];let scheduled=false;
function setActive(){let current=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<140)current=section}nav.forEach(a=>{const active=a.hash==='#'+current.id;a.classList.toggle('active',active);active?a.setAttribute('aria-current','location'):a.removeAttribute('aria-current')});scheduled=false}
window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(setActive)}},{passive:true});setActive();
const input=document.querySelector('#parameter-search');const rows=[...document.querySelectorAll('.parameter-table tbody tr')];
function filterParameters(){let n=0;const query=input.value.trim().toLocaleLowerCase();for(const row of rows){const show=row.textContent.toLocaleLowerCase().includes(query);row.hidden=!show;if(show)n++}document.querySelector('#parameter-count').textContent=`显示 ${n} / ${rows.length} 项`;document.querySelector('#parameter-empty').hidden=n!==0}input.addEventListener('input',filterParameters);
const viewer=document.querySelector('#viewer');const viewImg=viewer.querySelector('img');
document.querySelectorAll('.zoom').forEach(button=>button.addEventListener('click',()=>{const img=button.querySelector('img');viewImg.src=img.src;viewImg.alt=img.alt;document.querySelector('#viewer-title').textContent=img.alt;viewer.showModal()}));
viewer.querySelector('button').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});
let printState=[];let parameterState=[];function preparePrint(){printState=[...document.querySelectorAll('details')].map(d=>[d,d.open]);printState.forEach(([d])=>d.open=true);parameterState=rows.map(r=>[r,r.hidden]);rows.forEach(r=>r.hidden=false)}function restorePrint(){printState.forEach(([d,open])=>d.open=open);parameterState.forEach(([r,hidden])=>r.hidden=hidden);printState=[];parameterState=[]}
window.addEventListener('beforeprint',preparePrint);window.addEventListener('afterprint',restorePrint);document.querySelector('#print-button').addEventListener('click',()=>window.print());
'''
nav=''.join(f'<a href="#{id}"><em>{num}</em><span>{title.split("：")[0]}</span></a>' for id,num,title in sections)
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="熊猫领航评论客户工作台使用说明书：界面区域、账号集群、视频来源、AI与任务参数、客户状态及备份恢复。"><title>熊猫领航 · 产品使用说明书</title><style>'''+css+'''</style></head><body><aside class="toc" aria-label="说明书目录"><a class="brand" href="#top"><span class="brand-icon">熊</span>熊猫领航</a><div class="toc-sub">评论客户工作台 · 产品使用说明书</div><div class="toc-label">CONTENTS / 阅读导航</div><nav>'''+nav+'''</nav><div class="toc-bottom"><strong>配合当前客户端使用</strong>版本 0.1.0 · 开发版<br>校对于 2026.10.13<br>单文件 HTML · 可离线阅读</div></aside><main class="main" id="top"><div class="topbar"><button class="menu-toggle" aria-expanded="false">☰ 目录</button><span>熊猫领航 / 文档中心 / 使用说明</span><button id="print-button">打印 / 保存为 PDF</button></div><header class="hero"><div class="eyebrow">PRODUCT GUIDE · 产品使用指南</div><h1>从一条评论，<br>找到<span>值得跟进的需求。</span></h1><p class="hero-desc">熊猫领航 · 评论客户工作台使用说明书。了解每个界面区域、每项参数与完整操作流程，让客户发现、语义筛选和个性化触达有据可查。</p><div class="badges"><span>7 个功能区域</span><span>4 种视频来源</span><span>13 张当前界面图</span><span>参数逐项解读</span></div><div class="hero-panel"><div class="hero-panel-label">YOUR WORKFLOW / 操作主线</div><div class="hero-path"><a href="#start"><small>01 / 准备</small><strong>配置与登录</strong><span>连接 AI · 新增账号</span></a><a href="#sources"><small>02 / 发现</small><strong>整理视频来源</strong><span>关键词 · 搜索 · 博主 · 链接</span></a><a href="#customers"><small>03 / 筛选</small><strong>找到目标客户</strong><span>近期评论 · AI 语义判断</span></a><a href="#accounts"><small>04 / 跟进</small><strong>个性化私信</strong><span>核对文案 · 控制任务节奏</span></a></div></div><div class="note"><strong>阅读方式：</strong>首次使用从第 01 节开始；查看参数直接跳转第 06、07 节。点击界面图可放大，参数表可搜索，常见问题可展开。所有图片已内嵌，无需联网即可阅读。</div><noscript><p class="no-js">当前浏览器关闭了 JavaScript。正文与图片仍可阅读；搜索、放大与自动展开打印不可用，可用浏览器自带查找和打印。</p></noscript></header>'''+content+'''<footer><span>熊猫领航 · 评论客户工作台</span><span>使用说明书 / 2026.10 / v0.1.0</span></footer></main><a class="top-link" href="#top" aria-label="回到顶部">↑ 回到顶部</a><dialog id="viewer" aria-labelledby="viewer-title"><div class="viewer-bar"><span id="viewer-title"></span><button autofocus aria-label="关闭图片放大">关闭 · Esc</button></div><div class="viewer-image"><img alt=""></div></dialog><script>'''+js+'''</script></body></html>'''
output=ROOT/'docs'/'产品使用说明书.html'
output.write_text(page,encoding='utf-8')
print(f'Created {output.name}: {output.stat().st_size:,} bytes; {len(sections)} sections')
